def transform(g):
    cnt = Counter(c for r in g for c in r)
    base = cnt.most_common(1)[0][0]
    marker = next(c for c in cnt if c != base)
    fill = 2
    out = [row[:] for row in g]
    for row in out:
        n = len(row); i = 0
        while i < n:
            if row[i] not in (marker, base):
                i += 1; continue
            j = i
            while j < n and row[j] in (marker, base) and (j == i or row[j] != row[j-1]):
                j += 1
            seg = row[i:j]
            if seg.count(marker) >= 2:
                mid = [k for k, c in enumerate(seg) if c == marker]
                lo, hi = mid[0], mid[-1]
                for k in range(lo+1, hi):
                    if seg[k] == base:
                        row[i+k] = fill
            elif seg.count(marker) == 1:
                row[i] = base
            i = j
    return out
